stepxmp.pre:
.fade {
    mask-image: linear-gradient(to right, black, transparent);
}
.dots {
    mask-image: radial-gradient(circle at 15px 25px, black 12px, transparent 13px);
    mask-size: 30px 50px;
}
.stamp {
    mask-image: url(stamp.png);
    mask-position: right bottom;
    mask-repeat: no-repeat;
}
